// The strkrs.save layout the MSBL save editor relies on: entry key hashes, character blocks and the
// payloads that mark cups as completed. Values were measured on real saves (see docs/save-tools.md).

export const FILE_NAME = "strkrs.save";
export const COIN_HASH = 0xcfb400c8;
export const CHARACTER_HEADER_TAG = 0xb5d1609d;
export const CHARACTER_FIELD_TAG = 0xce8ae847;
/** Mario has no block before his own; his equipped gear sits in a separate entry. */
export const MARIO_LOADOUT_HASH = 0x4ca89276;
export const BUSHIDO_UNLOCK_HASH = 0xeadc176b;

export const CHARACTER_NAMES = [
  "Mario",
  "Luigi",
  "Bowser",
  "Peach",
  "Rosalina",
  "Toad",
  "Yoshi",
  "Donkey Kong",
  "Wario",
  "Waluigi",
  "Shy Guy",
  "Daisy",
  "Pauline",
  "Diddy Kong",
  "Bowser Jr",
  "Birdo",
] as const;

export const GEAR_PARTS = ["HEAD", "ARMS", "BODY", "LEGS"] as const;
export type GearPart = (typeof GEAR_PARTS)[number];
/** Byte of each gear part inside a 4-byte character field. */
export const BYTE_INDEX_BY_PART: Readonly<Record<GearPart, number>> = { HEAD: 0, ARMS: 2, BODY: 1, LEGS: 3 };
/** Character field holding "bought" for gear sets 1..9. */
export const SET_FIELD_POSITIONS = [1, 4, 2, 6, 3, 5, 7, 8, 9];
/** Gear Builder digit (0..9) to the gear id the save stores as equipped. */
export const BUILDER_DIGIT_TO_LOADOUT_ID = [0, 1, 4, 2, 6, 3, 5, 7, 8, 9];

export interface PayloadSpec {
  readonly label: string;
  readonly keyHash: number;
  readonly payloadHex: string;
}

